add_filter( 'woocommerce_catalog_orderby', 'perfectpixel_on_sale_sort_option' );
add_action( 'woocommerce_product_query', 'perfectpixel_on_sale_sort_query' );

function perfectpixel_on_sale_sort_option( $options ) {
	$options['on_sale'] = '{{on_sale_sort_label}}';
	return $options;
}

function perfectpixel_on_sale_sort_query( $q ) {
	if ( isset( $_GET['orderby'] ) && 'on_sale' === wc_clean( wp_unslash( $_GET['orderby'] ) ) ) {
		$ids = wc_get_product_ids_on_sale();
		$q->set( 'post__in', $ids ? array_values( array_unique( array_map( 'intval', $ids ) ) ) : array( 0 ) );
	}
}
